+function applyHunks(a, hunks) {
+  if (!Array.isArray(a)) throw new TypeError('applyHunks expects an array of lines');
+  if (!Array.isArray(hunks)) throw new TypeError('applyHunks expects an array of hunks');
+  const out = [];
+  let cursor = 0; // next unconsumed index in a
+  for (let h = 0; h < hunks.length; h++) {
+    const fail = (why) => new Error(`hunk ${h} does not apply: ${why}`);
+    const hunk = hunks[h];
+    if (hunk === null || typeof hunk !== 'object') throw fail('not an object');
+    const { oldStart, oldLines, newStart, newLines, lines } = hunk;
+    for (const [name, value] of [['oldStart', oldStart], ['oldLines', oldLines],
+      ['newStart', newStart], ['newLines', newLines]]) {
+      if (!Number.isInteger(value) || value < 0) throw fail(`invalid ${name}`);
+    }
+    if (!Array.isArray(lines)) throw fail('lines is not an array');
+    let oldCount = 0;
+    let newCount = 0;
+    for (const line of lines) {
+      if (typeof line !== 'string' || line.length === 0) throw fail('malformed line');
+      const p = line[0];
+      if (p === ' ') {
+        oldCount++;
+        newCount++;
+      } else if (p === '-') {
+        oldCount++;
+      } else if (p === '+') {
+        newCount++;
+      } else {
+        throw fail('malformed line prefix');
+      }
+    }
+    if (oldCount !== oldLines) throw fail('oldLines does not match lines');
+    if (newCount !== newLines) throw fail('newLines does not match lines');
+
+    if (oldLines > 0 && oldStart === 0) throw fail('invalid oldStart');
+    const index = oldLines === 0 ? oldStart : oldStart - 1;
+    if (index < cursor) throw fail('overlaps or precedes an earlier hunk');
+    if (index + oldLines > a.length) throw fail('extends past end of input');
+
+    for (let i = cursor; i < index; i++) out.push(a[i]);
+    const newIndex = out.length;
+    const expectedNewStart = newLines === 0 ? newIndex : newIndex + 1;
+    if (newStart !== expectedNewStart) throw fail('newStart does not match');
+
+    let pos = index;
+    for (const line of lines) {
+      const p = line[0];
+      const text = line.slice(1);
+      if (p === '+') {
+        out.push(text);
+        continue;
+      }
+      if (a[pos] !== text) throw fail(`line ${pos + 1} does not match`);
+      if (p === ' ') out.push(text);
+      pos++;
+    }
+    cursor = pos;
+  }
+  for (let i = cursor; i < a.length; i++) out.push(a[i]);
+  return out;
